local _, ns = ...
local E = ns.DB.entries
E["item:head-of-arugal"] = {t="item",n="Head of Arugal",z="shadowfang",s="The Head of Arugal is the grisly trophy taken from the mad archmage atop Shadowfang Keep. Brought to the Forsaken at the Sepulcher, it serves as undeniable proof that the master of the local worgen has fallen.",h="The Head of Arugal is the grisly trophy taken from the mad archmage atop Shadowfang Keep.",sec={{t="Trophy of the Mad Archmage",b="Archmage Arugal has long cast a dark shadow across Silverpine Forest, commanding the lupine horrors from the ramparts of Shadowfang Keep. Claiming his severed head is the ultimate mandate given by Dalar Dawnweaver at the Sepulcher. To the Forsaken, the head is far more than a gruesome token; it signifies the removal of a potent spellcaster whose feral beasts impeded Lady Sylvanas's complete dominion over Silverpine. Presenting it to Dawnweaver confirms that the rogue archmage's foul sorcery has finally been severed from the land.",sp=0}},faq={{q="Who wants the Head of Arugal?",a="Dalar Dawnweaver, an emissary stationed at the Sepulcher in Silverpine Forest, demands the head as part of the task 'Arugal Must Die'.",al={"who needs arugals head","arugal head turn in","who takes head of arugal"},it="why_wanted"},{q="Where do you obtain the Head of Arugal?",a="It is severed from Archmage Arugal himself, who resides at the highest pinnacle of Shadowfang Keep overlooking Pyrewood Village and the Silverpine woods.",al={"how to get arugals head","arugal head drop","where is arugal's head"},it="origin",gp=true},{q="Why do the Forsaken want Arugal dead?",a="Arugal's presence and his pack of feral worgen prevent the Forsaken from securing Silverpine Forest as a safe strategic stronghold for Lady Sylvanas and the Undercity.",al={"why kill arugal","forsaken arugal reason","why does dalar want arugal dead"},it="motive"},{q="What happens after the head is turned in?",a="Dalar Dawnweaver vows to eradicate the remnants of Arugal's foul spells, declaring that Silverpine is finally freed from the mad wizard's vice.",al={"after arugal dies","result of arugal must die"},sp=1,it="next_step"},{q="What is the Head of Arugal?",a="The Head of Arugal is the severed head of Archmage Arugal, the mad former wizard of Dalaran who unleashed the worgen upon Silverpine Forest. Taken from his fortress in Shadowfang Keep, it serves as undeniable physical proof that the crazed sorcerer has finally been slain and his dark magics broken.",al={"what is head of arugal","head of arugal item","arugal head"},it="identity",add=true},{q="Where does the Head of Arugal come from?",a="The head is claimed directly from Archmage Arugal within the heights of Shadowfang Keep. After invading the cursed fortress and overcoming the mad archmage in battle, you strike him down and claim his head to confirm his demise.",al={"where do you get head of arugal","who drops head of arugal","arugals head origin"},it="origin",add=true}},ang={["race:Undead"]="For the Forsaken, delivering Arugal's head eliminates a volatile sorcerer on their southern doorstep, securing Silverpine Forest for the Dark Lady.",["class:Mage"]="The severed head of a former Kirin Tor archmage serves as a stark warning of the madness and ruin that unchecked, desperate summonings can bring upon even gifted practitioners."},kw={"arugal","arugal must die","dalar dawnweaver","head of arugal","sepulcher","shadowfang keep","silverpine"},rel={"npc:arugal","quest:1014","npc:dalar-dawnweaver","zone:shadowfang","zone:silverpine","subzone:sepulcher","topic:lordaeron","topic:mage"},src={"Head of Arugal","Arugal Must Die"}}
E["item:the-book-of-ur"] = {t="item",n="The Book of Ur",z="shadowfang",s="The Book of Ur is a scholarly magical treatise penned by the late Dalaran wizard Ur, detailing his research into strange extradimensional entities. Left behind in Shadowfang Keep, it fell into the hands of Archmage Arugal before drawing the keen interest of Forsaken researchers in the Undercity.",h="The Book of Ur is a scholarly magical treatise penned by the late Dalaran wizard Ur, detailing his research...",sec={{t="The Mage of Dalaran",b="Before Dalaran fell to the Scourge, Ur was renowned among the Kirin Tor for his esoteric investigations into other planes of existence and otherworldly creatures. Despite his fascination with extraplanar magic, Ur was guided by caution and ethical restraint, choosing to record his discoveries rather than recklessly breach the veil between worlds. Tragically, when the Scourge assaulted the violet city, his magical prowess and moral hesitations were not enough to save him.",sp=0},{t="Forsaken Ambition",b="Following Ur's death, his writings found their way into the possession of Archmage Arugal, who used the research to summon the monstrous worgen into Silverpine Forest. The tome now rests within the shelves of Shadowfang Keep. Word of its existence caught the attention of Keeper Bel'dugur in the Undercity's Apothecarium. Unlike its original author, the Forsaken hold no reservations about using dangerous, uninhibited magic to ensure their survival and conquest.",sp=1}},faq={{q="Who was Ur?",a="Ur was a prominent human mage of Dalaran prior to the Third War. He extensively researched other dimensions and extraplanar creatures, though he refused to summon them due to the immense danger they posed.",al={"who wrote the book of ur","ur dalaran mage"},it="people"},{q="Where is the Book of Ur located?",a="The book rests on a shelf inside Shadowfang Keep in Silverpine Forest, specifically within the chamber where the massive beast Fenrus resides.",al={"book of ur location","where is book of ur"},it="place",gp=true},{q="Why does Keeper Bel'dugur want the book?",a="Keeper Bel'dugur collects Ur's writings on behalf of interested parties in the Undercity. The Forsaken believe Ur's moral conscience held him back from true power, and they seek to harness his extraplanar research without any ethical limitations to bolster their own strength.",al={"keeper bel'dugur book of ur","why undercity wants the book"},it="why_wanted"},{q="How did the book end up in Shadowfang Keep?",a="After Ur died during the fall of Dalaran, Archmage Arugal acquired his research. Driven to desperate measures to defend against the Scourge, Arugal brought the notes to Silverpine Forest and used Ur's summoning theories to draw the worgen into Azeroth.",al={"arugal and book of ur","how did arugal get the book"},it="history"},{q="What is the Book of Ur?",a="The Book of Ur is a scholarly tome containing the esoteric research of Ur, an accomplished mage of Dalaran. It details his extensive studies into other worlds and dangerous arcane phenomena—knowledge that proved so potent that Archmage Arugal later used Ur's writings to summon the monstrous worgen into Silverpine Forest.",al={"what is book of ur","book of ur lore","what is the book of ur"},it="identity",add=true},{q="Where does the Book of Ur come from, and who made it?",a="The book was penned in the magical kingdom of Dalaran by the mage Ur prior to the Scourge's destruction of the city. Ur documented his arcane theories and explorations into other dimensions, though his work was abandoned following his demise during the fall of Dalaran.",al={"who wrote the book of ur","book of ur origin","where did the book of ur come from"},it="origin",add=true}},ang={["race:Undead"]="Securing Ur's work directly aids the Dark Lady's scholars in the Apothecarium, turning the cautious research of a fallen human wizard into practical power for the Forsaken.",["class:Mage"]="Ur's writings are a stark reminder of Dalaran's scholarly reach into other realms—and the lethal consequences when ambitious magi like Arugal misuse that forbidden knowledge."},kw={"apothecarium","arugal","book of ur","dalaran","keeper bel'dugur","shadowfang keep","silverpine","ur"},rel={"quest:1013","npc:arugal","npc:keeper-bel-dugur","zone:shadowfang","subzone:apothecarium","subzone:dalaran","topic:forsaken","zone:silverpine"},src={"The Book of Ur","The Book of Ur (quest)"}}
E["npc:arugal"] = {t="npc",n="Arugal",z="shadowfang",s="Archmage Arugal is a former wizard of Dalaran and Gilneas who unleashed the feral worgen upon Lordaeron. Overcome by madness and grief, he now rules from the heights of Shadowfang Keep, treating the savage beasts as his beloved children while menacing all of Silverpine Forest.",h="Archmage Arugal is a former wizard of Dalaran and Gilneas who unleashed the feral worgen upon Lordaeron.",sec={{t="A Desperate Summons",b="Before the fall of Lordaeron, Arugal was a member of the Kirin Tor, though some peers like Dalar Dawnweaver dismissed him as a charlatan whose weak spellcraft relied heavily on enchanted trinkets. When the Scourge swept across the north during the Third War, Arugal sought a weapon powerful enough to stem the tide. Drawing upon the esoteric research of the late Dalaran mage Ur, Arugal pierced the veil between realms and summoned the worgen into the mortal world. The ravenous beasts tore through the undead legions as intended, but their feral ferocity could not be contained, and their savage hunger swiftly turned against innocent mortals.",sp=0},{t="Fall into Madness",b="The summoned horrors slaughtered the Gilnean soldiers stationed outside the Greymane Wall and spread their dreadful affliction through Gilneas. Some of the beasts then besieged the ancestral seat of Baron Silverlaine, and the keep fell swiftly to claws and fangs, its lord and retainers slain in the massacre. Rather than flee from his monstrous creation, Arugal's mind fractured under the weight of guilt, and he adopted the beasts as his own offspring. Renaming the fortress Shadowfang Keep, Arugal entrenched himself within its ramparts, surrounded by ghostly victims and loyal hound-packs.",sp=0},{t="The Scourge of Silverpine",b="From his high perch in Shadowfang Keep, Arugal extends his twisted dominion over the surrounding countryside. His dark sorcery blankets Pyrewood Village, where townsfolk live under a nocturnal curse, and infests the Deep Elem Mine with ravenous Moonrage beasts. He works intricate enchantments allowing select favored servants to retain human intellect while yielding entirely to his will. The Forsaken now view him as an intolerable threat; Sylvanas Windrunner's Deathstalkers and apothecaries actively plot the mad archmage's execution to secure the borders of their fledgling kingdom.",sp=1}},faq={{q="Who is Arugal?",a="Arugal is a former human archmage of the Kirin Tor and Gilneas. During the Third War, he summoned the monstrous worgen to battle the Scourge. Overwhelmed by his actions, he retreated into Shadowfang Keep, where he now leads packs of worgen as their self-proclaimed father.",al={"who is arugal","arugal backstory","shadowfang boss lore"},it="identity"},{q="Why did Arugal summon the worgen?",a="During the Third War, the Scourge threatened to overrun northern Lordaeron and Gilneas. Desperate for a weapon to halt the undead, Arugal utilized the extraplanar research of the Dalaran mage Ur. He believed the savage beasts could destroy the Scourge, but he lost control of the creatures once summoned.",al={"why worgen","why summon beasts","arugal worgen motive"},it="motive"},{q="Where does Arugal reside right now?",a="Arugal makes his lair at the pinnacle of Shadowfang Keep, an ancient fortress situated on the sea cliffs above Pyrewood Village in southern Silverpine Forest. He is guarded by his monstrous wolf pet, Fenrus, alongside swarms of loyal worgen and restless spirits.",al={"where is arugal","arugal location","find arugal"},it="place"},{q="What happened to Baron Silverlaine?",a="Baron Silverlaine was the noble lord who originally ruled the fortress and the village of Pyrewood. When Arugal's worgen besieged the castle, Silverlaine and his court were brutally slaughtered. Their vengeful, tortured ghosts now haunt the blood-stained halls of the keep.",al={"baron silverlaine fate","who owned shadowfang","keep history"},it="history"},{q="Why do the Forsaken want Arugal dead?",a="Arugal's packs terrorize Silverpine Forest, attacking Forsaken scouts, ambushing patrols, and even infecting loyal servants of the Royal Apothecary Society. Sylvanas Windrunner considers the mad archmage a direct threat to the security and expansion of the Undercity's borders.",al={"forsaken vs arugal","arugal must die quest","why kill arugal"},it="threat"},{q="What is the curse on Pyrewood Village?",a="Arugal cast wretched enchantments across the region, subjecting the human inhabitants of Pyrewood Village to the worgen curse. By daylight, the villagers appear as normal human subjects, but come nightfall, they transform into vicious beasts bound to defend Arugal's territory.",al={"pyrewood curse","why are pyrewood villagers wolves","pyrewood arugal"}},{q="Whose side is Archmage Arugal on?",a="Arugal serves neither the Alliance nor the Horde. Once a patriot of Gilneas and a member of Dalaran's Kirin Tor, he severed all former ties after falling into madness. Today he leads his own feral pack within Shadowfang Keep, considering the worgen his true children and violently rejecting both Kirin Tor envoys and the Forsaken.",al={"arugal faction","who does arugal serve","is arugal horde or alliance"},it="side",add=true},{q="What does Archmage Arugal want?",a="Consumed by guilt and madness after unleashing the worgen upon the world, Arugal now seeks to shelter, command, and expand his pack. He uses enchanted magic to bind the beasts to his will, spreading the worgen curse throughout Silverpine Forest to build his dark family and slaughter anyone who dares invade his domain.",al={"arugal goal","what is arugal trying to do","arugal motive"},it="wants",add=true},{q="Why is Archmage Arugal in Shadowfang Keep?",a="After the summoned worgen broke past control, they assaulted the fortress belonging to Baron Silverlaine above Pyrewood Village. Driven mad by the catastrophe he orchestrated, Arugal adopted the ferocious beasts as his children, took over the ruined keep, and renamed it Shadowfang to rule his pack in secluded dominance.",al={"why is arugal here","why did arugal go to shadowfang","how did arugal get shadowfang keep"},it="why_here",add=true},{q="Why is Archmage Arugal feared?",a="Arugal is infamous across Lordaeron for tapping into Ur's forbidden research to unleash the feral worgen upon the world. The curse he brought forth did not just slay the Scourge; it infected nearby lands, transformed peaceful villagers into bloodthirsty beasts, and turned an entire region into a nightmare under his erratic magical sway.",al={"why is arugal famous","arugal reputation","why is arugal dangerous"},it="fame",add=true}},ang={["faction:Horde"]="Arugal's worgen infest the road south of the Sepulcher, and Lady Sylvanas has ordered his execution to secure Silverpine Forest for the Forsaken.",["race:Undead"]="Arugal's beasts have killed several Deathstalkers and apothecaries; putting an end to his madness is a vital task for the Royal Apothecary Society.",["class:Mage"]="Arugal represents the catastrophic danger of reckless conjuration, turning the deep research of the Kirin Tor into an uncontrollable nightmare."},kw={"arugal","kirin tor","pyrewood","shadowfang","silverlaine","silverpine","ur","worgen"},rel={"zone:shadowfang","zone:silverpine","topic:worgen","quest:1014","quest:99","subzone:pyrewood-village","npc:baron-silverlaine","npc:dalar-dawnweaver"},src={"Arugal"}}
E["npc:baron-silverlaine"] = {t="npc",n="Baron Silverlaine",z="shadowfang",s="Baron Silverlaine was the rightful human lord of the fortress once known as Keep Silverlaine, perched high above Pyrewood Village. When Archmage Arugal unleashed the savage worgen upon the region, the baron and his household were mercilessly slaughtered. Now, his tormented spirit lingers in the ruined dining hall, bound in undeath to defend the very lair that became his tomb.",h="Baron Silverlaine was the rightful human lord of the fortress once known as Keep Silverlaine, perched high...",sec={{t="The Fall of Keep Silverlaine",b="Before the shadow of the wolf-beasts blanketed the southern hills of Silverpine, Baron Silverlaine ruled over a proud noble estate. His fortress provided safety and oversight to the surrounding Gilnean lands. That peace shattered when Archmage Arugal, seeking a weapon against the rampaging Scourge, unleashed summoned worgen into the region. The feral monstrosities could not be controlled; they stormed the stronghold, overran its guards, and butchered the baron along with his entire family.",sp=0},{t="A Tormented Specter",b="Death brought no release to Baron Silverlaine. Bound to the keep's ancient Great Hall, his restless ghost now wanders the trashed dining tables where he once feasted. In a cruel twist of dark magic, the cursed lord lashes out at any intruders who enter his ruined home, strangely compelled to summon the spectral forms of the very beasts that tore his flesh apart in life.",sp=0}},faq={{q="Who was Baron Silverlaine?",a="He was the noble Gilnean human master of the fortress originally named Keep Silverlaine, situated above Pyrewood Village. He was slain alongside his family when worgen overran the fortress.",al={"baron silverlaine lore","who is silverlaine","who ruled shadowfang"},it="identity"},{q="Why is he haunting Shadowfang Keep?",a="Silverlaine was slaughtered in his own home during the worgen onslaught unleashed by Archmage Arugal. Cursed in death, his ghost remains tethered to the dining hall of his ruined keep, unable to move on.",al={"why is silverlaine a ghost","is silverlaine dead","silverlaine spirit"},it="why_here"},{q="Why does he summon worgen spirits if they killed him?",a="The dark curse binding him within Shadowfang Keep twists his tragic fate into a perpetual nightmare. In his spectral madness, the baron's anguish manifests the phantoms of the very wolf-beasts that butchered his household.",al={"why does silverlaine use worgen","silverlaine worgen ghosts","silverlaine adds"}},{q="Where in the keep can he be found?",a="Baron Silverlaine haunts the Great Hall, which served as the keep's lavish dining room before it was wrecked during the fall of his estate.",al={"where is silverlaine","baron silverlaine location","silverlaine dining hall"},it="place",gp=true},{q="What was Shadowfang Keep called before the worgen attack?",a="It was originally called Keep Silverlaine, named after the baron's noble family who held dominion over it before Arugal took control.",al={"shadowfang original name","keep silverlaine lore","old name of shadowfang"},it="history"},{q="Did anyone in Silverlaine's family survive?",a="No. Historical accounts confirm that Baron Silverlaine and his entire family were slaughtered inside the keep when the feral worgen invaded.",al={"silverlaine family","did silverlaines family live","silverlaine heirs"}},{q="Whose side is Baron Silverlaine on?",a="Baron Silverlaine fights for no one but himself and the tragic memories of his ruined estate. Though he was murdered alongside his court when Archmage Arugal unleashed the feral worgen upon the castle, death has warped his spectral mind. Bound by a bitter curse, he strikes out indiscriminately at any living trespassers who enter his dining hall.",al={"baron silverlaine faction","who does silverlaine fight for","is baron silverlaine with arugal"},it="side",add=true},{q="What does Baron Silverlaine want?",a="Trapped as a vengeful phantom, Baron Silverlaine seeks only to drive away or slaughter anyone who dares invade his home. Tormented by the violent slaughter of his household, his spirit lashes out in relentless rage, commanding spectral worgen to punish those who disturb the ancient halls of his keep.",al={"what does silverlaine want","baron silverlaine goal","why does silverlaine attack"},it="wants",add=true},{q="Who is Baron Silverlaine tied to?",a="Baron Silverlaine's tragic fate is bound to Archmage Arugal. When Arugal summoned the extradimensional worgen to fight the Scourge, the beasts turned ravenous and invaded Silverlaine's home. Arugal usurped the fortress as Shadowfang Keep, leaving the Baron and his slain family to linger as restless spirits bound to the very beasts that tore them apart.",al={"silverlaine ties","who is silverlaine connected to","baron silverlaine and arugal"},it="ties",add=true}},ang={["race:Human"]="Silverlaine stands as a bitter testament to the downfall of human noble authority on the borders of Gilneas, his family wiped out by the magical hubris of a Dalaran-trained wizard.",["race:Undead"]="For the Forsaken pushing across Silverpine, Silverlaine's specter is merely another remnant of old Gilnean aristocracy that must be cleared to break Arugal's grip on the keep.",["class:Mage"]="Silverlaine's fate serves as a grim warning of magical recklessness; the summoner's art, when mishandled as Archmage Arugal did, destroys innocent lives and leaves indelible scars."},kw={"arugal","baron","ghost","great hall","keep","pyrewood","shadowfang","silverlaine","worgen"},rel={"zone:shadowfang","npc:arugal","topic:worgen","topic:scourge","topic:alliance","topic:horde"},src={"Baron Silverlaine"}}
E["npc:commander-springvale"] = {t="npc",n="Commander Springvale",z="shadowfang",s="Commander Springvale was once a devoted paladin and the head of Baron Silverlaine's armed guard at Shadowfang Keep. Slain alongside his men during the feral worgen slaughter orchestrated by Archmage Arugal, his vengeful spirit remains behind to haunt the castle halls. Even in death, his ghost fiercely guards the keep and seeks vengeance for his fallen master.",h="Commander Springvale was once a devoted paladin and the head of Baron Silverlaine's armed guard at Shadowfang...",sec={{t="The Fallen Commander",b="Before the ruin of Shadowfang Keep, Commander Springvale stood as an honorable paladin dedicated to the Holy Light and a sworn defender of Baron Silverlaine. Leading the garrison in Silverpine Forest, he oversaw the keep's security during the fraught days following the fall of Lordaeron to the Scourge.",sp=0},{t="Arugal's Folly",b="When Archmage Arugal summoned the extraplanar worgen to repel the undead Scourge encroaching upon Gilnean soil, the wild beasts quickly slipped from the mage's control. The ravenous pack descended upon the fortress, slaughtering Baron Silverlaine and his entire guard. Springvale perished in the halls he had sworn to protect, his service violently cut short.",sp=0},{t="An Unholy Vigil",b="Death offered no release to Springvale's bound soul. Twisted by trauma and necromantic energy, his ghost lingers within the keep's stone chambers. Though he carried the teachings of the Light in life, his phantom now strikes out with unholy power, blindly executing an eternal duty to avenge the slain Baron against any trespasser who sets foot inside the keep.",sp=0}},faq={{q="Who was Commander Springvale in life?",a="Commander Springvale was a paladin of the Holy Light who served as the commander of Baron Silverlaine's armed forces. He was tasked with the defense of Shadowfang Keep and remained fiercely loyal to the Baron until his death.",al={"springvale backstory","who is commander springvale","is springvale a paladin"},it="identity"},{q="How did Commander Springvale die?",a="He was killed when Archmage Arugal summoned feral worgen to fight the Scourge. The untamed beasts turned upon the inhabitants of Shadowfang Keep, massacring Baron Silverlaine, Springvale, and the garrison.",al={"how did springvale die","who killed springvale","springvale death"},it="ruin"},{q="Why is Commander Springvale haunting Shadowfang Keep?",a="Twisted in death, his spirit remains bound by his final oaths. Springvale's ghost wanders the halls to defend the ruins and seek vengeance for his fallen lord against all who enter.",al={"why is springvale a ghost","springvale motive","why does springvale fight"},it="why_here"},{q="Why does a former paladin use unholy powers?",a="The violent trauma of his death and the dark magic pervading the keep corrupted his spirit. In his spectral state, the holy vows he once wielded have warped into vengeful, unholy power.",al={"why unholy magic","springvale unholy abilities","corrupted paladin"},it="power"},{q="Who was his master?",a="Commander Springvale served Baron Silverlaine, the noble ruler and master of Shadowfang Keep before Arugal's beasts devastated the estate.",al={"springvale master","who did springvale serve","springvale and silverlaine"},it="ties"},{q="Where in the keep can he be found?",a="Commander Springvale's ghost is encountered deep within the keep, haunting the fortified chambers near the castle chapel and council rooms.",al={"springvale location","where is springvale","shadowfang springvale room"},it="place",gp=true},{q="Whose side is Commander Springvale on?",a="Commander Springvale serves no living master, nor is he allied with Archmage Arugal or the worgen that overrun the keep. In life, he swore unwavering loyalty to Baron Silverlaine, and even in death, his ghost remains bound to that solemn oath. He fights solely on behalf of his fallen lord, striking down any living trespassers who enter the castle halls.",al={"springvale faction","who does springvale serve","springvale allegiance"},it="side",add=true},{q="What does Commander Springvale want?",a="Even in death, Commander Springvale is driven by an obsessive desire to avenge Baron Silverlaine and protect his lord's ruined domain. Blinded by fury and corrupted into undeath, he vents his unholy wrath upon any intruders who dare set foot within Shadowfang Keep.",al={"springvale goal","what is springvale trying to do","springvale motive"},it="wants",add=true}},ang={["class:Paladin"]="Springvale is a sobering reminder of how duty and sacred vows can curdle into eternal torment when an honorable knight is bound to a corrupted grave.",["faction:Alliance"]="Springvale represents the lost soldiers of Lordaeron and Gilneas, loyal defenders who fell not to the Scourge directly, but to the reckless summonings meant to stop them.",["faction:Horde"]="For the Forsaken reclaiming Silverpine Forest, laying the commander's shade to rest is another step in purging the remnants of Arugal's tragic failure."},kw={"arugal","commander","ghost","paladin","shadowfang","silverlaine","silverpine","springvale","worgen"},rel={"zone:shadowfang","npc:baron-silverlaine","npc:arugal","topic:worgen","topic:light","topic:scourge","topic:alliance","topic:horde"},src={"Commander Springvale"}}
E["npc:deathstalker-vincent"] = {t="npc",n="Deathstalker Vincent",z="shadowfang",s="Deathstalker Vincent was a Forsaken scout sent alongside Deathstalker Adamant to infiltrate Shadowfang Keep. Slain by the mad mage Arugal, his corpse remains inside the stronghold as a grim warning to any who challenge the feral worgen within.",h="Deathstalker Vincent was a Forsaken scout sent alongside Deathstalker Adamant to infiltrate Shadowfang Keep.",sec={{t="A Scout's Fatal End",b="Before the Forsaken could launch a full-scale assault against the beasts holding Shadowfang Keep, intelligence on the fortress's interior was desperately needed. Two operatives from the Deathstalkers, the intelligence arm of the Forsaken, slipped past the barricades: Vincent and Adamant. Their mission ended in disaster. While Adamant was captured and locked away in a dungeon cell, Vincent was dragged directly before Shadowfang's master. Refusing to bend the knee or serve Arugal's dark designs, Vincent was executed on the spot, his body discarded on the stone floor to rot as a testament to the mage's fury.",sp=0},{t="Arugal's Defiance",b="Arugal used Vincent's demise to issue a scathing declaration to the intruders in his keep. Confronting the captive operative, the mad mage mocked the Forsaken and compared their intrusion to the failed efforts of his former Kirin Tor comrades. Demanding that Vincent surrender his blade and secrets to his master, Arugal struck the scout down when he refused, declaring that Vincent's moldering remains would serve as a warning to anyone foolish enough to trespass in his domain.",sp=1}},faq={{q="Who was Deathstalker Vincent?",a="Vincent was a Forsaken scout belonging to the Deathstalkers. He was dispatched with Deathstalker Adamant to gather critical reconnaissance inside Shadowfang Keep ahead of a planned assault by the Undercity.",al={"who is vincent","vincent shadowfang keep","dead rogue shadowfang"},it="identity"},{q="What happened to Vincent in Shadowfang Keep?",a="Vincent was captured during his reconnaissance mission and executed by Archmage Arugal after refusing to defect or offer intelligence against the Forsaken. Arugal left his corpse where it fell as a display of power.",al={"how did vincent die","why is vincent dead","who killed vincent"},it="conflict"},{q="Where is his partner, Deathstalker Adamant?",a="While Vincent was executed out in the open, Deathstalker Adamant was captured alive and locked in a nearby dungeon cell under the watchful eye of a worgen guard.",al={"where is adamant","other deathstalker","adamant location"},it="ties"},{q="Why were the Deathstalkers sent to Shadowfang Keep?",a="Silverpine Forest is vital territory for Sylvanas and the Forsaken, but Arugal's worgen hold the regional fortress of Shadowfang Keep. Vincent and Adamant were sent to scout the layout and defenses so the Forsaken could mount an effective offensive.",al={"why are deathstalkers in shadowfang","forsaken mission shadowfang"},it="why_here"},{q="Whose side is Deathstalker Vincent on?",a="Vincent is an operative of the Deathstalkers, the elite espionage and assassination order serving Lady Sylvanas Windrunner and the Forsaken. He acts on behalf of the Undercity to scout enemy strongholds and eliminate threats to their fledgling kingdom.",al={"vincent faction","who does vincent serve","vincent allegiance"},it="side",add=true},{q="What does Deathstalker Vincent want?",a="Vincent sought to gather vital reconnaissance within Shadowfang Keep to enable an assault by the Forsaken. Defiant to the end, he refused Archmage Arugal's demand to turn traitor and pledge his blade to Arugal and his mysterious master.",al={"what was vincent trying to do","vincent goal","vincent objective"},it="wants",add=true}},ang={["faction:Horde"]="Finding Vincent confirms the worst fears of the Forsaken commanders in Silverpine: the reconnaissance team failed, and the keep must now be cleared by force.",["class:Rogue"]="Vincent's execution stands as a sobering reminder of the risks faced by stealth operatives infiltrating hostile strongholds alone."},kw={"arugal","deathstalker adamant","deathstalker vincent","shadowfang keep","silverpine forest","vincent","worgen"},rel={"quest:1098","zone:shadowfang","npc:arugal","topic:forsaken","topic:worgen","topic:horde"},src={"Deathstalker Vincent"}}
E["npc:fenrus-the-devourer"] = {t="npc",n="Fenrus the Devourer",z="shadowfang",s="Fenrus the Devourer is an enormous worg that prowls the upper sanctum of Shadowfang Keep. Kept as a personal pet and guardian by Archmage Arugal, the ravenous beast is bloated on unnatural magics. Anyone daring to breach the archmage's personal study must contend with this feral horror and the master who watches over it.",h="Fenrus the Devourer is an enormous worg that prowls the upper sanctum of Shadowfang Keep.",sec={{t="A Beast in the Master's Study",b="Deep within Shadowfang Keep, just outside Archmage Arugal's personal chambers, lurks the monstrous worg known as Fenrus the Devourer. Unlike the lupine worgen roaming the ramparts, Fenrus is an actual worg, swollen to gargantuan proportions. Prowling the shelves, scrolls, and arcane apparatuses of Arugal's private study, the beast serves both as a pet and as a violent perimeter guard against any intruder seeking the mad mage's head.",sp=0},{t="Corrupted Might",b="Fenrus's unnatural bulk suggests he was subjected to the dark magics saturating the keep since Baron Silverlaine's downfall. Archmage Arugal or his unleashed worgen clearly warped the creature with arcane or shadowy experiments, transforming a native predator into a ravenous juggernaut. Fenrus is so feral and magically bound that no hunter can charm or tame his mind.",sp=0},{t="Arugal's Watchful Eye",b="Disturbing Fenrus is an immediate death sentence for the careless. When the beast spots an intruder, it lets loose an ear-splitting howl that echoes across the entire fortress, drawing the direct attention of Arugal himself. Rather than leaving his pet undefended, the archmage projects his dark will into the chamber, summoning voidwalkers to assist Fenrus in overwhelming and devouring invaders.",sp=1}},faq={{q="What kind of creature is Fenrus?",a="Fenrus is an exceptionally large worg, a natural wolf-like predator indigenous to Lordaeron, rather than a bipedal worgen. His unnatural bulk and vicious ferocity are the direct results of prolonged exposure to the dark magic practicing within Shadowfang Keep.",al={"is fenrus a worgen","fenrus creature type","fenrus wolf"},it="identity"},{q="Where can Fenrus be found?",a="Fenrus prowls the study chambers high inside Shadowfang Keep in Silverpine Forest. His lair is situated directly along the approach to Archmage Arugal's inner redoubt.",al={"where is fenrus","fenrus location","fenrus room"},it="place",gp=true},{q="Can hunters tame Fenrus as a pet?",a="No. Despite being an ordinary beast by classification, Fenrus cannot be tamed. His mind is thoroughly broken, feral, and tied to Archmage Arugal's dark will.",al={"can i tame fenrus","is fenrus tameable","taming fenrus"},gp=true},{q="Why does Arugal summon demons when Fenrus is attacked?",a="Arugal views Fenrus as his prized pet and final line of defense before his sanctum. When Fenrus bellows upon entering combat, Arugal intervenes directly, conjuring voidwalkers into the chamber to overwhelm whoever threatens his beast.",al={"arugal voidwalkers","why does arugal help fenrus","fenrus voidwalker add"},it="ties"},{q="Why is Fenrus so much larger than normal worgs?",a="Fenrus's massive size is believed to be the consequence of Archmage Arugal's dark magical experimentation, or magical fallout from the worgen infestation overtaking the keep.",al={"why is fenrus huge","fenrus size lore","giant worg"},it="power"},{q="What happens across the dungeon when Fenrus is engaged?",a="When Fenrus engages in combat, he unleashes a thunderous roar so loud it can be heard by anyone anywhere inside Shadowfang Keep, alerting all to the battle taking place outside Arugal's door.",al={"fenrus roar","fenrus howl across dungeon","loud roar sfk"},it="fame"},{q="Whose side is Fenrus on?",a="Fenrus is fiercely loyal to Archmage Arugal. As the sorcerer's personal beast and guardian, he serves whatever twisted will drives the master of Shadowfang Keep, attacking any intruder who trespasses into the upper sanctum without hesitation.",al={"fenrus faction","who does fenrus serve","fenrus loyalties"},it="side",add=true},{q="Why is Fenrus in Shadowfang Keep?",a="Fenrus prowls the main study directly adjoining Arugal's personal chambers. He acts as both a pet and a monstrous guard dog, placed there to tear apart anyone seeking to breach the inner sanctum of the archmage.",al={"why is fenrus here","fenrus location purpose","why does fenrus guard the study"},it="why_here",add=true}},ang={["class:Hunter"]="Do not waste time attempting to charm Fenrus. The beast's mind is irrevocably twisted by Shadowfang's dark arts and cannot be bound by the wild.",["class:Warlock"]="Archmage Arugal's ability to summon voidwalkers to aid his hound reveals how deeply the former Dalaran mage has delved into shadowy, forbidden conjurations.",["class:Mage"]="Fenrus stands as a grim reminder of how far Archmage Arugal has fallen, using arcane arts to warp wild beasts into grotesque domestic guardians."},kw={"arugal","fenrus","fenrus the devourer","shadowfang keep","silverpine","worg"},rel={"npc:arugal","zone:shadowfang","topic:worgen"},src={"Fenrus the Devourer"}}
E["npc:keeper-bel-dugur"] = {t="npc",n="Keeper Bel'dugur",z="shadowfang",s="Keeper Bel'dugur is a scholarly Forsaken residing deep within the Apothecarium of the Undercity. He serves his people by commissioning expeditions to recover dark tomes and magical artifacts from across Azeroth.",h="Keeper Bel'dugur is a scholarly Forsaken residing deep within the Apothecarium of the Undercity.",sec={{t="A Collector of Dark Relics",b="Situated among the vats and researchers of the Apothecarium, Keeper Bel'dugur tasks adventurers with retrieving dangerous arcane and occult relics from across Azeroth. Among his most prominent interests is the Book of Ur, a legendary treatise on extra-dimensional beings locked away inside Shadowfang Keep. While many in the Undercity seek magical knowledge to cure or weaponize the condition of the undead, Bel'dugur's curated acquisitions appear tailored toward unearthing ancient, forbidden powers.",sp=0},{t="Hidden Loyalties",b="Beneath his calm demeanor as an Undercity researcher lies a covert loyalty to the apocalyptic Twilight's Hammer cult. The quests and research tasks Bel'dugur assigns quietly further the cult's esoteric agenda, acquiring foundational grimoires of summoning and void magic under the unsuspecting nose of the Royal Apothecary Society and Lady Sylvanas.",sp=2}},faq={{q="Where can I find Keeper Bel'dugur?",a="Keeper Bel'dugur is located in the Apothecarium, the alchemical district nestled within the southern lower ring of the Undercity.",al={"keeper bel'dugur location","where is beldugur","beldugur map"},it="place",gp=true},{q="Why does Bel'dugur want The Book of Ur?",a="The Book of Ur contains the foundational research of the Dalaran mage Ur regarding other dimensions and the feral worgen. Bel'dugur seeks to harness these forbidden summoning principles for the dark schemes of his true masters.",al={"why book of ur","what does beldugur do with book of ur"},sp=1,it="why_wanted"},{q="Is Keeper Bel'dugur loyal to Lady Sylvanas?",a="Outwardly, he functions as an archivist and researcher for the Forsaken, though subtle hints in his investigations suggest his loyalties may lie elsewhere.",al={"is beldugur evil","beldugur faction","who does beldugur serve"},sp=2,it="side"},{q="What other tasks does he give adventurers?",a="Beyond Shadowfang Keep's Book of Ur, Bel'dugur directs travelers toward forgotten lore and forbidden tomes, including dark treatises tied to ancient rituals and forbidden knowledge.",al={"beldugur quests","keeper beldugur quests"},gp=true},{q="Who is Keeper Bel'dugur?",a="Keeper Bel'dugur is a Forsaken scholar stationed in the Apothecarium within the Undercity. While he presents himself as a quiet archivist collecting obscure tomes and forgotten lore for the Royal Apothecary Society, he pursues dangerous esoteric knowledge far beyond ordinary apothecary craft.",al={"who is bel'dugur","keeper beldugur lore","who is keeper beldugur"},it="identity",add=true},{q="What does Keeper Bel'dugur want?",a="Bel'dugur seeks forbidden arcane texts, occult secrets, and relics of dark power. He tasks adventurers with retrieving dangerous tomes such as The Book of Ur from Shadowfang Keep and other hidden digests to unlock perilous ancient magic.",al={"what does beldugur want","keeper beldugur motives","beldugur goal"},it="wants",add=true},{q="Why is Keeper Bel'dugur in the Undercity?",a="Bel'dugur resides in the Apothecarium of the Undercity, an ideal sanctuary for those pursuing dark studies away from prying eyes. From the safety of the Forsaken capital, he directs wanderers to dangerous corners of the world to recover lost writings for his collection.",al={"why is bel'dugur in undercity","why is keeper beldugur here","beldugur location why"},it="why_here",add=true},{q="Who is Keeper Bel'dugur tied to?",a="Beneath his role among the Forsaken in the Apothecarium, subtle clues and dialogue surrounding his forbidden research suggest ties to the secretive Twilight's Hammer cult, which covets world-shaking power and apocalyptic lore.",al={"keeper bel'dugur connections","who does beldugur work for","beldugur twilight's hammer"},sp=1,it="ties",add=true}},ang={["race:Undead"]="Bel'dugur seems like any other scholarly Forsaken seeking forbidden knowledge to bolster your kingdom, but his true ambitions lie outside the Banshee Queen's survivalist cause.",["class:Warlock"]="Warlocks frequently cross paths with Bel'dugur's requests, as his interests align heavily with dangerous grimoires, extraplanar summoning, and dark occultism."},kw={"apothecarium","bel'dugur","keeper beldugur","shadowfang","the book of ur","undercity"},rel={"subzone:apothecarium","zone:undercity","quest:1013","topic:twilight-s-hammer","zone:shadowfang","topic:forsaken"},src={"Keeper Bel'dugur"}}
E["quest:1013"] = {t="quest",n="The Book of Ur",z="shadowfang",s="The Book of Ur is a mission assigned by Keeper Bel'dugur in the Undercity's Apothecarium. Bel'dugur charges Horde champions with infiltrating Shadowfang Keep to recover the arcane treatise of Ur, a deceased mage of Dalaran. The Forsaken seek Ur's extraplanar research, intending to weaponize magical insights he was too scrupulous to exploit.",h="The Book of Ur is a mission assigned by Keeper Bel'dugur in the Undercity's Apothecarium.",sec={{t="A Relic of Extramundane Magic",b="Before the Third War wiped out Dalaran, a brilliant human wizard named Ur dedicated his scholarship to realms beyond Azeroth. Unlike standard Kirin Tor doctrine, which strictly regulated conjuration and outer planar contacts, Ur cataloged entities from other dimensions, including the savage worgen. Despite his curiosity, Ur ultimately hesitated to manipulate these alien powers, deeming them dangerously uncontrollable. That restraint, however, made his written legacy a coveted prize for those who possess no such moral qualms.",sp=0},{t="The Fall into Dark Hands",b="Following Ur's demise during the Scourge invasion of Dalaran, his works scattered. His definitive treatise found its way into the clutches of Archmage Arugal, a grieving and unstable wizard who holed up in Shadowfang Keep. Arugal lacked Ur's ethical reservations and used the book's contents to summon bloodthirsty worgen into Silverpine, unleashing a curse that devoured Pyrewood and the surrounding valleys. The volume now rests neglected inside the keep's towers, watched over by Arugal's feral pets.",sp=0},{t="The Forsaken's Ambition",b="To the Royal Apothecary Society and Keeper Bel'dugur, Ur's downfall was not a cautionary tale of hubris, but an example of mortal frailty. Bel'dugur believes Ur perished because conscience paralyzed him at the moment of crisis. By securing the Book of Ur for the Undercity, the Forsaken intend to strip the text of its academic hesitation, harnessing extradimensional lore to ensure their survival and enforce Sylvanas Windrunner's dominion across Lordaeron.",sp=1}},faq={{q="Who was Ur?",a="Ur was a notable Dalaran mage who studied magical phenomena and other worlds prior to the Third War. He extensively researched extradimensional creatures, including the worgen, before being killed during the Scourge invasion of Dalaran.",al={"ur lore","who is ur","mage ur"},it="identity"},{q="Where is the Book of Ur located?",a="The book rests inside Shadowfang Keep, resting on a bookshelf within the chamber belonging to Fenrus the Devourer, deep within the fortress.",al={"where is the book","book of ur location","shadowfang book location"},gp=true},{q="Who is Keeper Bel'dugur?",a="Keeper Bel'dugur is a Forsaken archivist and researcher stationed in the Apothecarium of the Undercity. He gathers dark, arcane, and extramundane lore to advance the power and survival of the Forsaken.",al={"beldugur","keeper bel dugur","quest giver"},it="in_charge"},{q="Why does the Forsaken want the book?",a="Bel'dugur and his cohort desire Ur's research into extraplanar entities. The Forsaken believe Ur failed to survive the Scourge only because his moral conscience held him back from exploiting the powers he discovered—a hesitation the Undercity has no intention of repeating.",al={"why do forsaken want ur's book","undercity purpose book of ur"},it="motive"},{q="How did the book end up in Shadowfang Keep?",a="After Dalaran's fall, Archmage Arugal acquired Ur's notes and utilized them to summon the worgen into Lordaeron. Arugal brought the research to Shadowfang Keep when he seized the fortress.",al={"how did arugal get the book","why is the book in sfk"},it="history"},{q="Is the Book of Ur related to the worgen curse?",a="Yes. Ur's research detailed the terrifying dimension from which worgen originate. Arugal used the treatise to unleash those beasts upon Silverpine Forest, resulting in the infestation plaguing the region.",al={"worgen origin book","book of ur worgen"},it="origin"},{q="What is the Book of Ur?",a="The Book of Ur is a prized arcane tome written by the late Dalaran mage Ur before the Scourge fell upon Lordaeron. Ur dedicated his studies to extradimensional realms and strange, otherworldly beasts—including the savage worgen. While Ur possessed immense magical knowledge, he ultimately refused to meddle too deeply with these lethal forces due to his moral conscience. To the Forsaken, who disdain such ethical hesitation, his research offers invaluable secrets into other worlds and dangerous planar entities.",al={"what is the book of ur","book of ur lore","contents of book of ur"},it="item",add=true}},ang={["class:Mage"]="The Book of Ur serves as a grim artifact of Kirin Tor history, showing how Dalaran's theoretical research into otherworldly entities could be twisted into apocalyptic curses by unstable practitioners like Arugal.",["class:Warlock"]="Ur's willingness to peer beyond mortal reality mirrors a warlock's hunger for extraplanar knowledge, though Bel'dugur notes that Ur's failure lay in lacking the nerve to wield what he discovered.",["race:Undead"]="Retrieving the book directly serves Lady Sylvanas and the Royal Apothecary Society, reinforcing the Forsaken belief that survival requires embracing forbidden lore without mortal squeamishness.",["faction:Horde"]="Clearing Shadowfang Keep and securing Arugal's sources helps stabilize Silverpine Forest, curbing the feral worgen menace encroaching on Horde-held territories."},kw={"apothecarium","arugal","bel'dugur","book of ur","dalaran","fenrus","kirin tor","shadowfang keep","worgen"},rel={"npc:keeper-bel-dugur","zone:shadowfang","subzone:apothecarium","zone:undercity","subzone:dalaran","topic:forsaken","topic:scourge"},m={start="Keeper Bel'dugur",level="26",faction="Horde",id=1013,ri={"The Book of Ur"}},src={"The Book of Ur (quest)"}}
E["quest:1014"] = {t="quest",n="Arugal Must Die",z="shadowfang",s="Arugal Must Die is a decisive Horde mission issued by Dalar Dawnweaver at the Sepulcher. It tasks brave champions with storming Shadowfang Keep to slay the rogue archmage Archmage Arugal and claim his severed head. Eliminating Arugal is critical for Lady Sylvanas Windrunner to break the worgen menace and secure Silverpine Forest for the Forsaken.",h="Arugal Must Die is a decisive Horde mission issued by Dalar Dawnweaver at the Sepulcher.",sec={{t="A Thorn in the Dark Lady's Side",b="While the Forsaken have carved out a base in the Sepulcher, Silverpine Forest remains treacherous and deeply contested. Perched high upon the cliffs overlooking the woods sits Shadowfang Keep, the lair of Archmage Arugal. Driven mad by guilt and dark sorcery, Arugal unleashed the feral worgen upon Lordaeron. His ravenous beasts roam the forest paths, directly hindering Lady Sylvanas Windrunner's efforts to establish a fortified strategic hold over the region.",sp=0},{t="Striking the Beast at the Neck",b="Dalar Dawnweaver recognizes that merely hunting wandering beasts in the forest will never cleanse the land. The heart of the corruption beats within Shadowfang Keep itself. Horde champions must breach the ancient stronghold, fight through Arugal's devoted worgen brood, and confront the mad wizard in his aerie. Bringing his head back to the Sepulcher finally shatters his magical hold over the region, clearing the way for Forsaken supremacy.",sp=0}},faq={{q="Why does Dalar Dawnweaver want Arugal dead?",a="Dalar Dawnweaver acts under the orders of the Dark Lady. Arugal's worgen overrun Silverpine Forest, making it impossible for the Forsaken to turn the region into a secure strategic stronghold until the mad mage is slain.",al={"why kill arugal","dalar dawnweaver goal","arugal target"},it="motive"},{q="Where can Arugal be found?",a="Archmage Arugal resides at the very peak of Shadowfang Keep, a grim fortress looming over southern Silverpine Forest.",al={"where is arugal","arugal location","find arugal"},it="place",gp=true},{q="What proof is required to complete the mission?",a="Dalar Dawnweaver requires tangible proof of the wizard's demise: champions must retrieve and present the severed Head of Arugal.",al={"what does dalar need","arugal head quest","proof of death"},it="item",gp=true},{q="What threat does Arugal pose to the Horde?",a="Beyond his potent offensive magics, Arugal commands legions of cursed worgen that harass Horde forces and threaten Forsaken control throughout Silverpine Forest.",al={"why is arugal dangerous","worgen threat silverpine","is arugal a threat"},it="threat"},{q="Who does Dalar Dawnweaver serve?",a="Dalar Dawnweaver serves Lady Sylvanas Windrunner and the Forsaken, operating out of the Sepulcher to consolidate Forsaken control across Lordaeron.",al={"who does dawnweaver work for","sepulcher leadership"},it="side"},{q="What happens after Arugal is defeated?",a="With Arugal's death, his foul magical grip over Silverpine is broken, allowing the Forsaken to expand their dominance across western Lordaeron without fear of his coordinated worgen packs.",al={"after arugal dies","result of arugal death"},sp=1,it="next_step"},{q="What is the Head of Arugal for?",a="Dalar Dawnweaver demands the severed head of Archmage Arugal as undeniable proof that the mad wizard's reign over Shadowfang Keep has ended. Beyond simple confirmation of the kill, Dalar intends to personally examine the remains to unravel and eradicate the foul, lingering magic Arugal cast over Silverpine Forest, ensuring his curse can no longer threaten the Forsaken.",al={"head of arugal purpose","why take arugals head","what does dalar do with arugal head"},it="item",add=true},{q="Who is Archmage Arugal?",a="Archmage Arugal was once a wizard of the Kirin Tor in Dalaran. Driven to madness, he unleashed the ferocious worgen upon Lordaeron to combat the Scourge, only to lose control of the beasts. Retreating to Shadowfang Keep, he slaughtered Baron Silverlaine and claimed the fortress as his own, adopting the feral monsters as his cursed 'children' and terrorizing Silverpine Forest ever since.",al={"who is arugal","shadowfang keep boss arugal","why is arugal in shadowfang"},it="target",add=true}},ang={["race:Undead"]="For the Forsaken, eliminating Arugal secures their southwestern border and ensures the safety of routes connecting the Sepulcher to the Undercity.",["faction:Horde"]="Taking down Arugal demonstrates the Horde's growing martial reach in the Eastern Kingdoms, breaking an entrenched wizard and freeing vital roads.",["class:Mage"]="Confronting Arugal serves as a cautionary tale of arcane hubris, pitting practitioners of the magical arts against a Kirin Tor mage warped by otherworldly summons."},kw={"arugal","dalar dawnweaver","head of arugal","sepulcher","shadowfang keep","silverpine","sylvanas","worgen"},rel={"npc:arugal","npc:dalar-dawnweaver","zone:shadowfang","zone:silverpine","subzone:sepulcher","topic:lordaeron"},m={start="Dalar Dawnweaver",level="27",faction="Horde",id=1014,ri={"Head of Arugal"}},src={"Arugal Must Die"}}
E["quest:1098"] = {t="quest",n="Deathstalkers in Shadowfang",z="shadowfang",s="High Executor Hadrec dispatches Horde adventurers into Shadowfang Keep to locate two missing reconnaissance agents, Deathstalker Adamant and Deathstalker Vincent. The Forsaken military relies on their gathered intelligence to coordinate an assault against Archmage Arugal and his worgen packs. Breaching the fortress reveals the grim reality of espionage behind enemy lines.",h="High Executor Hadrec dispatches Horde adventurers into Shadowfang Keep to locate two missing reconnaissance...",sec={{t="Into the Worgen Den",b="Silverpine Forest remains contested ground, with Archmage Arugal's feral worgen holding the towering redoubt of Shadowfang Keep. Seeking to break this siege on their southern borders, the Forsaken command stationed at the Sepulcher organized an intelligence operation. High Executor Hadrec sent two seasoned Deathstalkers—Adamant and Vincent—to infiltrate the fortress and chart its defenses. When days passed without word, Hadrec grew desperate for their field reports, tasking capable Horde champions with entering the stronghold to recover the agents and salvage the mission.",sp=0},{t="A Bitter Discovery",b="Upon fighting their way through the lower ramparts, adventurers discover the heavy price of the infiltration. While Deathstalker Adamant survives in captivity and assists in unbarring the courtyard gates, Vincent met a brutal end. His broken corpse lies motionless within the keep, his personal intelligence lost to the dark halls. Only a small trinket remains clenched in his cold fingers, serving as quiet testament to a spy who gave his unlife for the Dark Lady's conquest.",sp=1}},faq={{q="Why were Deathstalkers sent to Shadowfang Keep?",a="High Executor Hadrec ordered the infiltration to gather vital tactical intelligence on Archmage Arugal's forces and fortifications before committing Forsaken troops to a full-scale assault on Shadowfang Keep.",al={"why send spies to shadowfang","hadrec mission purpose","deathstalker goal shadowfang"},it="purpose"},{q="Who are Deathstalkers Adamant and Vincent?",a="They are elite Forsaken operatives belonging to the Deathstalkers, the espionage and assassination branch of the Undercity. Sent ahead as advance scouts, they were tasked with mapping Shadowfang Keep and observing the worgen defenses.",al={"who are adamant and vincent","adamant and vincent lore"},it="people"},{q="What happened to Deathstalker Vincent?",a="Vincent was killed by the denizens of the keep during the mission. Adventurers find his broken body lying just beyond the courtyard gate, clutching a small trinket in his hand.",al={"did vincent die","where is vincent","vincent fate"},sp=1},{q="What role does Deathstalker Adamant play inside the keep?",a="Adamant survives the initial infiltration, though he is trapped. When adventurers reach him, he helps unlock the courtyard gate, allowing the assault deeper into the fortress to proceed while he relays what intelligence he can back to Hadrec.",al={"what does adamant do","deathstalker adamant role"},sp=1},{q="Where does this mission begin?",a="The mission is given by High Executor Hadrec, the Forsaken military commander stationed at the Sepulcher in Silverpine Forest.",al={"where to get deathstalkers in shadowfang","quest giver deathstalkers in shadowfang"},it="arrival"},{q="Why does the Forsaken leadership want Shadowfang Keep cleared?",a="Archmage Arugal unleashes violent worgen packs across Silverpine Forest from his perch in Shadowfang Keep, constantly threatening Forsaken holdings, supply lines, and the overall security of Lordaeron.",al={"why attack shadowfang","forsaken beef with arugal"},it="conflict"},{q="Why does High Executor Hadrec need you to find the Deathstalkers?",a="High Executor Hadrec is preparing a major Forsaken assault against Shadowfang Keep, but his entire strategy hinges on vital intelligence. He sent Deathstalkers Adamant and Vincent ahead to scout the fortress, but days have passed without word. Without their reconnaissance on the enemy's strength and defenses, any direct offensive would be marching blindly into slaughter.",al={"why does hadrec want this done","hadrec motive shadowfang","why search for the deathstalkers"},it="motive",add=true},{q="Why does High Executor Hadrec send you instead of his own troops?",a="The Sepulcher's standing forces are stretched thin holding the line across Silverpine, and committing an army to infiltrate Shadowfang without intelligence would invite disaster. Hadrec needs a resourceful, capable adventurer who can slip past the keep's outer perimeter, track down his missing elite scouts, and provide whatever aid they require to salvage the mission.",al={"why send me shadowfang","why not use deathstalkers or guards","why me hadrec"},it="why_me",add=true}},ang={["race:Undead"]="For the Forsaken, reclaiming Silverpine from Arugal's beasts is essential to securing the borders of Lordaeron, making Vincent's sacrifice a somber reminder of the cost of their freedom.",["class:Rogue"]="The fallen Vincent and the captured Adamant demonstrate the lethal risks of deep reconnaissance work behind heavily fortified enemy lines.",["faction:Horde"]="High Executor Hadrec relies on Horde champions to support Forsaken operations when conventional troops cannot breach Arugal's cursed fortress."},kw={"adamant","arugal","deathstalkers in shadowfang","hadrec","sepulcher","shadowfang keep","silverpine","vincent"},rel={"npc:high-executor-hadrec","npc:deathstalker-vincent","zone:shadowfang","quest:1886","quest:448"},m={start="High Executor Hadrec",["end"]="Deathstalker Vincent",level="25",faction="Horde",id=1098},src={"Deathstalkers in Shadowfang"}}
E["zone:shadowfang"] = {t="dungeon",n="Shadowfang Keep",z="shadowfang",s="Perched on the rugged bluffs above Pyrewood Village, Shadowfang Keep is the gloomy stronghold of the rogue Kirin Tor wizard, Archmage Arugal. Once the ancestral estate of Baron Silverlaine, the bastion now teems with feral worgen beasts and the tormented phantoms of its slaughtered defenders. For adventurers traversing southern Silverpine, the keep represents the dark epicenter of the beastly scourge consuming the region.",h="Perched on the rugged bluffs above Pyrewood Village, Shadowfang Keep is the gloomy stronghold of the rogue...",sec={{t="Fall of the Silverlaine Dynasty",b="Before it was shrouded in nightmare, Shadowfang was known as Silverlaine Keep, a noble seat loyal to Gilnean lords and garrisoned by the pious Commander Springvale. When the Scourge swept through Lordaeron during the Third War, Dalaran's wizards fell in droves. Desperate to stem the rising dead, Archmage Arugal defied Kirin Tor leadership and delved into the research of the wizard Ur, summoning extra-dimensional worgen to turn the tide. The summoned beasts savaged the undead, but rapidly slipped beyond all mortal control, breaking into southern Silverpine and storming the bastion. Baron Silverlaine and his entire court were massacred, doomed to haunt the stone halls alongside the feral monsters that overran their home.",sp=0},{t="Arugal's Children",b="Broken by guilt and madness, Arugal retreated within the blood-stained battlements, adopting the ravenous wolf-men as his beloved 'children' and christening the castle Shadowfang Keep. Deep in the stone roosts, lupine packs and shadowy hounds flourish under trainers like Wolf Master Nandos, watched over by Arugal's massive lupine beast, Fenrus the Devourer. Outside the walls, the curse did not halt; nearby Pyrewood Village remains trapped in a horrifying nocturnal cycle, its residents walking as men by day and hunting as ravenous worgen beneath the moon, tethered inexorably to the mad archmage perched on the heights above.",sp=0},{t="The Forsaken Strike",b="Recognizing the dire threat Arugal poses to their dominion in Silverpine Forest, Lady Sylvanas Windrunner dispatched the Royal Apothecary Society and elite Deathstalkers to root out the source of the worgen curse. Infiltration teams suffered brutal casualties within the dungeons, but Horde heroes answering the call from the Sepulcher ultimately breach the highest tower. Striking down the Archmage brings a formal end to the master of the pack, severing the mind orchestrating the beasts' spread across the wilderness and claiming his head as proof of Lordaeron's vengeance.",sp=1}},faq={{q="What happens when Archmage Arugal is defeated?",a="Slaying Arugal decapitates the central force controlling the worgen packs in southern Silverpine. Horde adventurers deliver his severed head to Dalar Dawnweaver at the Sepulcher under orders from Lady Sylvanas Windrunner. While his demise breaks the direct will directing the Shadowfang pack, the feral beasts and ghostly remnants lingering in the keep and the surrounding woods remain a persistent danger to travelers.",al={"kill arugal outcome","arugal dead lore","what happens after arugal dies"},sp=1,it="next_step",nx={42,43}},{q="Why did Arugal summon the worgen?",a="During the Third War, the armies of Dalaran were suffering disastrous defeats against the Scourge. Fallen wizards continuously rose as undead soldiers for the Lich King. Seeking a weapon to turn the tide, Arugal used the arcane research of the wizard Ur to summon extra-dimensional worgen, believing their savagery could halt the Scourge.",al={"why worgen summoned","arugal motive","dalaran worgen summon"},it="motive"},{q="Who was Baron Silverlaine?",a="Baron Silverlaine was the human nobleman who ruled the keep and oversaw the neighboring hamlet of Pyrewood before the Third War. When Arugal's summoned beasts escaped control, they stormed the stronghold and butchered the baron, his household, and his guards. Silverlaine's vengeful ghost still haunts the great dining halls, cursed to walk alongside the monsters that slew him.",al={"baron silverlaine lore","original lord of shadowfang"},it="identity"},{q="Why are Pyrewood Village villagers friendly during the day?",a="Arugal subjected the inhabitants of nearby Pyrewood Village to his dark magic. By day, they retain their human form, minds, and peaceful demeanor toward Alliance travelers. At sundown, the curse takes hold, transforming the entire population into savage worgen loyal to the mad archmage in the keep.",al={"pyrewood humans","pyrewood curse","why pyrewood turns worgen"},it="threat"},{q="Who is Commander Springvale?",a="Commander Springvale was a paladin of the Silver Hand and the military officer responsible for defending Silverlaine Keep. When the worgen overrun the stronghold, he fought to the death. His restless spirit still patrols the upper hallways, clinging to martial duty even in undeath.",al={"springvale lore","ghostly paladin boss"},it="identity"},{q="What is the Book of Ur?",a="The Book of Ur is a tome containing the research of Ur, an archmage of Dalaran who studied extra-dimensional entities, including the worgen. Arugal used Ur's writings to perform his disastrous summons. The Royal Apothecary Society in the Undercity seeks the book to understand the nature of the wolf-creatures and their bizarre magic.",al={"book of ur quest","ur lore"},it="item"},{q="What is Shadowfang Keep?",a="Shadowfang Keep is a haunted castle perched on the high bluffs of southern Silverpine Forest, overlooking Pyrewood Village. Originally known as Silverlaine Keep, it once served as an Alliance stronghold guarding the borders near Gilneas. Today, it stands corrupted and shrouded in dark mists, serving as the stronghold for Archmage Arugal and his feral worgen progeny.",al={"what is shadowfang keep","tell me about shadowfang","shadowfang keep lore"},it="place",add=true,nx={8,9}},{q="Who built Shadowfang Keep?",a="The fortress was the seat of Baron Silverlaine, a noble whose family long held lordship over the surrounding lands and Pyrewood Village before the Third War. Under his rule, it stood as a proud human bastion, guarded by Commander Springvale and sworn soldiers of the realm.",al={"who built shadowfang keep","origin of shadowfang","who made shadowfang"},it="origin",add=true},{q="Why is Shadowfang Keep full of worgen?",a="When the summoned worgen broke free from Kirin Tor control, they rampaged through the forest and laid siege to the castle. They butchered Baron Silverlaine and his household. Driven mad by guilt over what he had unleashed, Archmage Arugal adopted the beasts as his own 'children,' claimed the ruin for himself, and renamed it Shadowfang Keep.",al={"why are there worgen here","shadowfang keep worgen why","why worgen inside"},it="threat",add=true},{q="Why is the Horde interested in this castle?",a="The worgen roaming out of the keep are an unchecked plague threatening the Forsaken's hold over Silverpine Forest. From their base at the Sepulcher, Forsaken leaders realized that as long as Arugal commands his lupine horrors from the castle heights, the surrounding lands will never be secure.",al={"why does the horde care about shadowfang","horde interest shadowfang","why come to shadowfang keep"},it="arrival",add=true,nx={11,12}},{q="Who sent me here?",a="Forsaken commanders at the Sepulcher ordered the assault to eliminate Arugal and discover the fate of their missing scouts. Meanwhile, the Royal Apothecary Society in the Undercity dispatched agents to retrieve Ur's magical research from the archmage's library.",al={"who sent me to shadowfang","shadowfang keep quest giver","who wants arugal dead"},it="motive",add=true},{q="Is this Forsaken land now?",a="The Forsaken claim northern Silverpine, but their hold on the south is hotly contested. Shadowfang Keep remains firmly under Arugal's dominion, while lingering Scourge, feral beasts, and surviving human settlements dispute the Dark Lady's rule across the region.",al={"is silverpine forsaken land","does sylvanas own this","forsaken territory shadowfang"},it="conflict",add=true},{q="Who is in charge in Shadowfang Keep?",a="The castle answers entirely to Archmage Arugal. Driven mad by the Third War, he rules the upper towers flanked by his monstrous worgen and massive pet worg, Fenrus, commanding the keep through dark sorcery.",al={"who rules shadowfang keep","who is in charge inside","shadowfang master"},it="in_charge",add=true,nx={14,15}},{q="Is Arugal the boss of the keep?",a="Yes. Arugal is the master of Shadowfang Keep. He orchestrates the worgen infestation across Silverpine and sits at the pinnacle of the keep's tower as its ultimate authority.",al={"is arugal the boss","final boss shadowfang","arugal master"},it="leader",add=true},{q="Was anyone in charge before him?",a="Baron Silverlaine ruled the keep when it was an Alliance redoubt. He and his family governed the castle until Arugal's worgen breached the walls and slaughtered everyone inside during the Third War.",al={"who ruled before arugal","previous master of shadowfang","past lord of the keep"},it="history",add=true},{q="Where do the worgen come from?",a="They are ravenous extra-dimensional beings torn from another plane. Desperate to stop the Scourge during the Third War, Arugal turned to the forbidden research of the Dalaran mage Ur and summoned these otherworldly beasts into Azeroth.",al={"where did worgen come from","origin of the worgen","worgen source"},it="threat",add=true,nx={17,18}},{q="Did Arugal summon the worgen alone?",a="Arugal performed the summoning against the explicit advice of his peers in Dalaran's Kirin Tor, though with the quiet desperation of Gilneas' leadership behind the wall. Relying heavily on the writings in the Book of Ur, he forced the entities across planar boundaries.",al={"did arugal act alone","who helped summon worgen","arugal summoning"},it="history",add=true},{q="Can the worgen be controlled?",a="Barely, and only through dark magic. Though summoned to serve as allies against the undead, they turned immediately on their summoners. Arugal manages to direct some of them only because his broken mind treats them as family, using enchantments to enforce fragile obedience.",al={"can worgen be controlled","controlling the worgen","are worgen tame"},it="danger",add=true},{q="What happened to the Deathstalkers Adamant and Vincent?",a="Deathstalkers Adamant and Vincent slipped into Shadowfang Keep on orders from the Sepulcher to scout Arugal's strength. They were captured by the keep's defenders; Vincent was imprisoned and executed in the courtyard, while Adamant lies trapped within the dungeons waiting for rescue.",al={"adamant and vincent","what happened to the deathstalkers","forsaken scouts shadowfang"},sp=1,it="purpose",add=true,nx={20,21}},{q="Why were the Deathstalkers sent into Shadowfang Keep?",a="Forsaken command needed precise intelligence on the beastly infestation threatening their southern front. Adamant and Vincent were tasked with infiltrating the keep, determining Arugal's true numbers, and paving the way for a decisive strike.",al={"why send deathstalkers","scouting shadowfang","deathstalker mission"},it="motive",add=true},{q="Are the Deathstalkers still alive?",a="Vincent is dead, struck down by Arugal upon capture. Adamant, however, remains imprisoned deep within the keep's lower holding cells, alive enough to assist any Horde adventurers who break through to him.",al={"are vincent and adamant alive","did deathstalkers survive","deathstalker fate"},sp=1,it="threat",add=true},{q="What are Deathstalkers?",a="The Deathstalkers are the elite covert assassins and rogues of the Forsaken. Specializing in stealth, espionage, and sudden death, they operate as the silent daggers of the Undercity across Lordaeron's frontiers.",al={"what is a deathstalker","who are deathstalkers","forsaken deathstalkers"},it="other",add=true,nx={23,24}},{q="Who do the Deathstalkers answer to?",a="They answer through a strict chain of command governed by Forsaken officers and commanders stationed across the territories, ultimately serving the will of the Undercity's ruling council.",al={"deathstalker leadership","who commands deathstalkers","who leads deathstalkers"},it="leader",add=true},{q="Do the Deathstalkers work for Sylvanas directly?",a="Yes. Every Deathstalker is sworn to the Banshee Queen, Lady Sylvanas Windrunner. They form her personal intelligence network, rooting out threats to her free-willed undead throughout Lordaeron.",al={"do deathstalkers serve sylvanas","sylvanas deathstalkers","deathstalkers banshee queen"},it="ties",add=true},{q="Why is everyone sending me into Shadowfang Keep?",a="Because the Forsaken's initial reconnaissance completely collapsed with the capture of their elite Deathstalkers. Arugal's lair is too treacherous for standard infantry, requiring proven adventurers who can cut through both beasts and vengeful spirits.",al={"why send me to shadowfang","why am i doing this","why hero shadowfang"},it="why_me",add=true,nx={26,27}},{q="Am I the only one left to do it?",a="Forsaken resources in Silverpine are stretched razor-thin battling Rot Hide gnolls, Scourge holdouts, and Dalaran patrols. With their own advance scouts compromised, you and your allies are the only force capable of breaching the keep.",al={"am i the only one","no one else to clear shadowfang","only choice"},it="purpose",add=true},{q="Did others try to breach the keep before me?",a="Yes. Beyond the failed Deathstalker scouts, Kirin Tor investigators such as Sorcerer Ashcrombe entered the keep to evaluate Arugal, only to end up captured or trapped within its cursed halls.",al={"did others try shadowfang","previous attempts shadowfang","who tried before"},it="history",add=true},{q="What happened to Silverpine Forest?",a="Silverpine was once a verdant realm of towering silver-barked pines guarded by the Alliance. When the Scourge swept Lordaeron during the Third War, the plague withered the woods, crops were burned, and its people were massacred or driven behind the Greymane Wall.",al={"silverpine history","what happened to silverpine","why is silverpine like this"},it="history",add=true,nx={29,30}},{q="Was Silverpine Lordaeron land?",a="Yes. Silverpine formed the rugged western edge of the Kingdom of Lordaeron, bordering Gilneas to the south. Its estates and settlements were bound to the Alliance before the plague shattered the kingdom.",al={"was this lordaeron","silverpine lordaeron history","did lordaeron own silverpine"},it="place",add=true},{q="Why is Silverpine Forest so empty now?",a="Between the Scourge invasion, Gilneas closing its great wall, and Arugal's rampaging worgen curse, the living population was slaughtered, cursed, or fled abroad. The few who remain cling desperately to contested hamlets like Pyrewood.",al={"why is silverpine empty","deserted silverpine","silverpine ruins why"},it="ruin",add=true},{q="Why did Arugal bring worgen to Silverpine in the first place?",a="When the undead Scourge marched south threatening the region and Dalaran fell, Gilneas and local defenders were facing annihilation. Arugal believed extra-dimensional summoned allies could overwhelm the undead where conventional mortal armies had failed.",al={"why bring worgen to silverpine","reason arugal summoned worgen","why summon worgen here"},it="history",add=true,nx={32,33}},{q="Who was Arugal trying to stop?",a="He summoned them specifically to annihilate the undead armies of the Scourge, which were swelling by slaughtering and raising every soldier and wizard that fell in battle.",al={"who was arugal fighting","arugal enemy","who did arugal summon worgen against"},it="threat",add=true},{q="Did Arugal's plan work against the Scourge?",a="Tactically, yes—the worgen effortlessly tore the undead apart. But strategically, it was a catastrophe. The feral wolf-men could not be controlled, turned upon human soldiers and wizards alike, and spread a deadly curse across the region.",al={"did worgen beat the scourge","did the summoning work","worgen success vs scourge"},it="conflict",add=true},{q="Are the worgen in the keep the same ones that overran Pyrewood?",a="Yes. Arugal's packs, including the Shadowfang and Moonrage packs, share the same cursed origin. The beasts stalking the castle halls are Arugal's personal brood, closely tied to the curse afflicting the villagers below.",al={"are shadowfang worgen from pyrewood","pyrewood worgen shadowfang","same worgen pack"},it="threat",add=true,nx={35,36}},{q="What happened to the Pyrewood villagers?",a="The villagers survived the Third War only to be ensnared by Arugal's dark magic. Though they appear as normal humans during daylight, sunset transforms them into savage, bloodthirsty worgen loyal to the mad archmage.",al={"what happened to pyrewood people","fate of pyrewood","pyrewood townsfolk"},it="people",add=true},{q="Are the Pyrewood villagers cursed too?",a="Yes. They are victims of the lycanthropic worgen curse. By day, they retain their minds and trade peacefully with Alliance wanderers; by night, the curse strips their humanity away, turning them into ravenous beasts.",al={"is pyrewood cursed","pyrewood curse","are villagers infected"},it="danger",add=true},{q="Who are the ghosts inside Shadowfang?",a="They are the restless spirits of Baron Silverlaine, Commander Springvale, and the castle's former household. Slain in the surprise worgen onslaught, their souls remain bound to the ruined stones by torment and grief.",al={"ghosts in shadowfang","who are the spirits in sfk","specters shadowfang"},it="threat",add=true,nx={38,39}},{q="Are the ghosts the old servants of the keep?",a="Yes. From ghostly cooks and shadowy attendants to former guardsmen, the spectral defenders wandering the halls are the slaughtered retainers who once attended Baron Silverlaine in life.",al={"are ghosts former servants","castle servants ghosts","silverlaine servants"},it="residents",add=true},{q="Why can't the ghosts rest?",a="The sheer horror of their slaughter, combined with the heavy shadow magic saturating the keep, prevents their release. In their perpetual anguish, they lash out with unholy hatred at any living trespasser who disturbs their graves.",al={"why are ghosts restless","why do spirits haunt shadowfang","unrest ghosts shadowfang"},it="threat",add=true},{q="Is Arugal working for the Scourge?",a="No. Arugal despises the Scourge; he summoned the worgen precisely to destroy them. Though he has gone mad, his loyalty belongs to his 'children' rather than the Lich King.",al={"is arugal scourge","arugal working for scourge","does arugal serve the scourge"},it="other",add=true,nx={41}},{q="Does the Lich King control Arugal?",a="No. Arugal's madness is entirely self-inflicted, born of guilt and planar magic rather than the telepathic grip of the Frozen Throne. He operates independently as master of his own dark domain.",al={"does lich king control arugal","lich king arugal","arugal mind control"},it="in_charge",add=true},{q="Does the curse end after Arugal is dead?",a="No. Slaying Arugal decapitates the leadership of Shadowfang Keep, but the worgen curse has already infected the blood of mortals across the forest. The affliction persists long after the archmage falls.",al={"does the worgen curse end","will worgen curse vanish","is pyrewood cured"},sp=1,it="threat",add=true},{q="Will the Forsaken take Shadowfang Keep?",a="For now, the Forsaken are content with eliminating the threat to their southern border and recovering the Book of Ur. The ruin remains a grim, haunted shell overlooking the woods rather than a garrisoned outpost.",al={"will forsaken take shadowfang","do forsaken capture shadowfang","who controls sfk after"},it="next_step",add=true},{q="How did I end up in Shadowfang Keep?",a="You followed the trail of terror through Silverpine Forest to the bluffs overlooking Pyrewood Village. If you serve the Horde, you were likely directed south from the Sepulcher or Undercity to investigate the worgen menace choking the region. If you fight for the Alliance, rumors of the cursed woods, lost holy relics, or the fallen Kirin Tor brought you deep into hostile Forsaken territory. Climbing the winding crags beyond Pyrewood's gates, you pushed past ravenous wolf-beasts and battered through the keep's ancient gateway to enter the lair of the mad archmage.",al={"how did i get here","how do i reach shadowfang keep","how did i find this place"},it="arrival",add=true},{q="What am I supposed to be doing in Shadowfang Keep?",a="Your ultimate goal is to fight through the haunted halls and strike down Archmage Arugal, ending his twisted reign over Silverpine. Along the way, you must cut down the worgen stalking the courtyards and put down the restless spirits of Baron Silverlaine and his slain household. If acting on behalf of the Forsaken, you are tasked with recovering the Book of Ur and discovering the fate of missing Deathstalkers sent inside. Alliance champions, paladins, and warlocks seek lost artifacts of power, holy armaments, and retribution against the dark magic poisoning the land.",al={"what am i doing here","why am i here","what is my goal in shadowfang keep"},it="purpose",add=true}},ang={["faction:Horde"]="The Forsaken view Arugal's encroaching packs as an immediate danger to their fledgling territory in Silverpine, making the keep a priority target for Deathstalker operatives and the Royal Apothecary Society.",["class:Mage"]="The tragedy of Shadowfang serves as a grim warning of what happens when a Kirin Tor wizard meddles in extra-dimensional summoning beyond mortal control.",["class:Warlock"]="The dark energies, voidwalkers, and fell sorceries inside the keep draw the interest of practitioners looking to recover ancient relics like the Orb of Soran'ruk.",["class:Paladin"]="The restless spirit of Commander Springvale stands as a sorrowful reminder of fallen Silver Hand defenders whose sacred oaths were warped by death."},kw={"arugal","fenrus","pyrewood","sfk","shadowfang","silverlaine","silverpine","springvale","worgen"},rel={"npc:arugal","npc:baron-silverlaine","npc:commander-springvale","quest:1014","quest:1013","subzone:pyrewood-village","zone:silverpine","topic:worgen"},m={levels="22-30"},src={"Shadowfang Keep (Classic)","Shadowfang Keep"}}
